  {"n": 704, "q": "¿Cómo se llamaba en la Atenas clásica el destierro de diez años decidido por votación?", "a": "Ostracismo", "cat": "historia", "dif": "dificil", "lz": "B", "alias": [], "sabias": "Se escribía el nombre en un trozo de cerámica, el «óstrakon», que dio nombre al ostracismo; el desterrado conservaba sus bienes."},
  {"n": 713, "q": "En ajedrez, ¿cómo acaba la partida si un jugador no puede mover y no está en jaque?", "a": "En tablas", "cat": "deporte", "dif": "dificil", "lz": "B", "alias": ["Tablas", "Empate", "Ahogado"], "sabias": "Se llama «rey ahogado». Es un recurso de quien va perdiendo: dejar al rival sin jugadas legales para salvar la partida."},
  {"n": 739, "q": "¿Cómo se conoce popularmente a la Constitución española de 1812?", "a": "La Pepa", "cat": "historia", "dif": "dificil", "lz": "A", "alias": [], "sabias": "Se proclamó en Cádiz el 19 de marzo, día de San José: de ahí el grito «¡Viva la Pepa!»."},
  {"n": 740, "q": "¿Qué obra anónima de 1554 inauguró la novela picaresca en España?", "a": "El Lazarillo de Tormes", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Vida de Lazarillo de Tormes"], "sabias": "Se publicó sin firma; la Inquisición la incluyó en su índice de libros prohibidos por su crítica al clero."},
  {"n": 741, "q": "¿Qué español ganó el Premio Nobel de Literatura en 1989?", "a": "Camilo José Cela", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": [], "sabias": "Su novela de 1942, «La familia de Pascual Duarte», inauguró el «tremendismo», un realismo crudo y violento."},
  {"n": 742, "q": "¿Qué filósofo ilustrado propuso dividir el poder en legislativo, ejecutivo y judicial?", "a": "Montesquieu", "cat": "historia", "dif": "dificil", "lz": "A", "alias": [], "sabias": "Lo expuso en «Del espíritu de las leyes» (1748); inspiró la Constitución de EE. UU. y casi todas las actuales."},
  {"n": 743, "q": "¿Qué filósofo del siglo XVII afirmó «Pienso, luego existo»?", "a": "Descartes", "cat": "cultura_general", "dif": "medio", "lz": "A", "alias": ["René Descartes"], "sabias": "Llegó a ella dudando de todo: lo único indudable era que, al dudar, estaba pensando."},
  {"n": 749, "q": "¿Qué emperador romano legalizó el cristianismo con el Edicto de Milán, en el año 313?", "a": "Constantino I", "cat": "historia", "dif": "dificil", "lz": "A", "alias": ["Constantino", "Constantino el Grande", "Constantino I el Grande"], "sabias": "Teodosio I lo convirtió en religión oficial del Imperio en el año 380."},
  {"n": 750, "q": "¿Cuántos países forman el Reino Unido?", "a": "Cuatro", "cat": "geografia", "dif": "medio", "lz": "B", "alias": ["4", "Cuatro países", "Cuatro naciones"], "sabias": "Inglaterra, Escocia, Gales e Irlanda del Norte; Gran Bretaña es solo la isla, sin Irlanda del Norte."},
  {"n": 751, "q": "¿Qué rey fue coronado emperador en Roma en el año 800 y unificó gran parte de Europa occidental?", "a": "Carlomagno", "cat": "historia", "dif": "dificil", "lz": "A", "alias": ["Carlos el Grande", "Carlos I el Grande", "Carolus Magnus"], "sabias": "Sus nietos dividieron el imperio en el 843, en el Tratado de Verdún: origen aproximado de Francia y Alemania."}
